import{_ as e,o as t,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"JD3 质数因子","description":"描述 功能:输入一个正整数，按照从小到大的顺序输出它的所有质因子（重复的也要列举）（如180的质因子为2 2 3 3 5 ） 数据范围： 1≤�≤2×109+14 1≤ n ≤2×109+14 输入描述： 输入一个整数 输出描述： 按照从小到大的顺序输出它的所有质数的因子，以空格。","frontmatter":{"title":"JD3 质数因子","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 功能:输入一个正整数，按照从小到大的顺序输出它的所有质因子（重复的也要列举）（如180的质因子为2 2 3 3 5 ） 数据范围： 1≤�≤2×109+14 1≤ n ≤2×109+14 输入描述： 输入一个整数 输出描述： 按照从小到大的顺序输出它的所有质数的因子，以空格。","sidebarWeight":78,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD3 质数因子.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD3 质数因子.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD3 质数因子.md"}'),i={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD3 质数因子.md"};function n(s,a,d,l,p,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<div><h1 id="jd3-质数因子" tabindex="-1">JD3 质数因子 <a class="header-anchor" href="#jd3-质数因子" aria-label="Permalink to &quot;JD3 质数因子&quot;">​</a></h1><blockquote><p>本节目标：理解“JD3 质数因子”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 功能:输入一个正整数，按照从小到大的顺序输出它的所有质因子（重复的也要列举）（如180的质因子为2 2 3 3 5 ） 数据范围： 1≤�≤2×109+14 1≤<em>n</em>≤2×109+14 <strong>输入描述：</strong> 输入一个整数 <strong>输出描述：</strong> 按照从小到大的顺序输出它的所有质数的因子，以空格隔开。 <strong>示例1</strong> 输入： 180 ==复制== 输出： 2 2 3 3 5</p></blockquote><p>要找到一个数的所有质数因子并按从小到大的顺序输出，你不需要显式地检查每个因子是否为质数。相反，你可以从最小的可能质数（2）开始尝试，依次除以这个数，直到它不再是原数的因子为止，然后移动到下一个数。如果某个数是给定数的因子，那么这个数必须是质数，因为我们从最小的质数开始，并且已经除去了所有比它小的质数的因子。</p><p>以下是这个方法的Python实现： def get_prime_factors(n):</p><h1 id="初始化一个空列表用来存储所有的质数因子" tabindex="-1">初始化一个空列表用来存储所有的质数因子 <a class="header-anchor" href="#初始化一个空列表用来存储所有的质数因子" aria-label="Permalink to &quot;初始化一个空列表用来存储所有的质数因子&quot;">​</a></h1><p>factors = []</p><h1 id="从2开始-尝试所有小于等于n的可能的质数因子" tabindex="-1">从2开始，尝试所有小于等于n的可能的质数因子 <a class="header-anchor" href="#从2开始-尝试所有小于等于n的可能的质数因子" aria-label="Permalink to &quot;从2开始，尝试所有小于等于n的可能的质数因子&quot;">​</a></h1><p>divisor = 2 while divisor * divisor &lt;= n:</p><h1 id="当divisor是n的因子时-添加到factors列表中-并除以divisor直到它不再是因子为止" tabindex="-1">当divisor是n的因子时，添加到factors列表中，并除以divisor直到它不再是因子为止 <a class="header-anchor" href="#当divisor是n的因子时-添加到factors列表中-并除以divisor直到它不再是因子为止" aria-label="Permalink to &quot;当divisor是n的因子时，添加到factors列表中，并除以divisor直到它不再是因子为止&quot;">​</a></h1><p>while n % divisor == 0: factors.append(divisor) n //= divisor divisor += 1</p><h1 id="如果n大于1-那么n是原数的一个质数因子" tabindex="-1">如果n大于1，那么n是原数的一个质数因子 <a class="header-anchor" href="#如果n大于1-那么n是原数的一个质数因子" aria-label="Permalink to &quot;如果n大于1，那么n是原数的一个质数因子&quot;">​</a></h1><p>if n &gt; 1: factors.append(n) return factors</p><h1 id="从用户输入中读取一个整数" tabindex="-1">从用户输入中读取一个整数 <a class="header-anchor" href="#从用户输入中读取一个整数" aria-label="Permalink to &quot;从用户输入中读取一个整数&quot;">​</a></h1><p>n = int(input())</p><h1 id="获取这个整数的所有质数因子" tabindex="-1">获取这个整数的所有质数因子 <a class="header-anchor" href="#获取这个整数的所有质数因子" aria-label="Permalink to &quot;获取这个整数的所有质数因子&quot;">​</a></h1><p>prime_factors = get_prime_factors(n)</p><h1 id="按照要求的格式输出这些质数因子" tabindex="-1">按照要求的格式输出这些质数因子 <a class="header-anchor" href="#按照要求的格式输出这些质数因子" aria-label="Permalink to &quot;按照要求的格式输出这些质数因子&quot;">​</a></h1><p>print(&quot; &quot;.join(map(str, prime_factors)))</p><p>这个实现利用了数学上的一个事实：任何合数都可以分解为一系列质数的乘积，而且这个分解是唯一的（基本定理算术）。通过从最小的质数开始除，我们可以确保找到的每个因子都是质数，从而避免了显式的质数检查。</p></div>',1)])])}const _=e(i,[["render",n]]);export{f as __pageData,_ as default};
